        + [M(f"What is the {t} of {r[0]}?", r[i], dd([x[i] for x in _CJ2], r[i]), r[i] + ".") for r in _CJ2 for i, t in ((2, "past"), (3, "present"), (4, "future"))]
        + [M(f"What is the root of {r[0]}?", r[1], dd([x[1] for x in _CJ2], r[1]), r[1] + ".") for r in _CJ2]
        + [M(f"What does {r[0].split(';')[0]} mean?", r[1], dd([x[1] for x in _VLIST], r[1]), r[1] + ".") for r in _VLIST]
        + [M("What is a reciprocal action?", "an exchange between two people who mutually share in the action", ["an action done alone", "an action done for others", "an action in the past"], "reciprocal."), M("Is the doer of a mag-an verb singular or plural?", "always plural", ["always singular", "either one", "neither"], "plural."), M("Which marker is used with the doer of a mag-an verb?", "Set 1 (ang, si, sina)", ["Set 2 (ng)", "Set 3 (sa)", "none"], "Set 1."), M("What do we do with a pronoun in a mag-an sentence?", "pluralize it", ["drop it", "make it past", "make it Set 3"], "pluralize."), M("Which marker follows a plural pronoun that includes the other person?", "Set 2 (ng, ni)", ["Set 1 (ang)", "Set 3 (sa)", "none"], "ni, ng."), M("Which is correct?", "Nagbibiruan sila ni Romeo", ["Nagbibiruan siya at si Julieta", "Nagbibiruan ako at si Julieta", "Nagbibiruan siya ni Julieta"], "pluralize."), M("Which is correct?", "Nagsulatan kami ng kapatid ko", ["Nagsulatan ako at ang kapatid ko", "Nagsulatan ako ng kapatid ko", "Nagsulatan kami at ng kapatid ko"], "kami ng.")]
        + [F("Magbibiruan ___ Romeo at si Julieta. (the plural marker for two names)", "sina", ["si", "ang"], "sina."), F("___ kami ng kapatid ko. (we wrote to each other)", "Nagsulatan", ["Nagsusulatan", "Magsusulatan"], "nagsulatan."), F("Magtutulungan ___ ng pinsan mo. (you and I and your cousin)", "tayo", ["siya", "ako"], "tayo."), F("Nagsuntukan ___. (they)", "sila", ["siya", "ako"], "sila.")]
