_A7 = [("Nakatipid ng tatlong bilyon isang daan at pitong milyon anim na raan at pitumpu’t walong libong piso ang hukuman sa paglilitis nung nakaraang taon dahil sa pagpapatupad ng Katarungang Pambarangay.", "The courts saved over three billion pesos in trials last year because of the implementation of the Katarungang Pambarangay."), ("Umabot sa tatlong daan at dalawampu’t pitong libo isang daan at dalawampu’t apat ang kasong nalutas sa labas ng korte.", "The cases settled outside of court reached three hundred twenty-seven thousand one hundred twenty-four."), ("Dalawang daan at limampu’t isang libo walong daan at siyamnapu’t apat na kaso ang nalutas dahil sa pagkakasundo.", "Two hundred fifty-one thousand eight hundred ninety-four cases were solved through conciliation."), ("Animnapu’t tatlong libo anim na raan at limampu’t isang kaso ang nalutas naman dahil sa pamamagitan.", "Sixty-three thousand six hundred fifty-one cases were solved through mediation."), ("Labing-isang libo limang daan at siyamnapu’t pitong kaso ang nalutas sa paraan ng paghatol.", "Eleven thousand five hundred ninety-seven cases were solved through judgment.")]
