_B8 = [("Barangay Onse Blog", "Mayroon po ba kayong tanong tungkol sa Katarungang pambarangay o sa mga kasong gusto ninyong ikuwento upang maayos bago dalhin ito sa Korte? Ipadala po ninyo dito sa Barangay Onse Blog. Tutulungan namin kayo! Salamat po!", "Do you have any question about the Katarungang Pambarangay or about cases you want to relate so that they can be settled before bringing them to court? Please send them here to the Barangay Onse Blog. We will help you! Thank you!"), ("Samuel Gonzales", "Magandang hapon po. May asawa at tatlong anak. Tanong ko, puwede bang kasuhan ang asawa kong may karelasyong ibang lalaki? Ang katibayan ko lang ang fb account niya.", "Good afternoon. I have a wife and three children. My question is, can I file a case against my wife who has a relationship with another man? My only evidence is her fb account."), ("Samuel Gonzales", "Paano naman kung nakita ko siyang ilang beses na nakikipaglandian sa ibang lalaki? Wala naman akong maipakita sa kort na iyon ang ginagawa niya.", "What if I saw her several times flirting with another man? I have nothing to show in court that this is what she is doing."), ("Samuel Gonzales", "Ano pa po ang dapat gawin?", "What else should be done?"), ("Samuel Gonzales", "Puwede bang mawalan siya ng karapatan sa mga anak namin? Ano po ba ang kasong dapat isampa sa kanya? Nagpapasalamat sa inyo.", "Can she lose her rights over our children? What case should be filed against her? Thank you.")]
_K8 = [("1. The main idea of the postings", "It is an announcement addressed to barangay constituents informing them that if they have questions about the Barangay Justice System or cases to be resolved, they can ask through the website before bringing the case to the court. The barangay will offer assistance to the best of their ability."), ("2. Two descriptions of the writer", "(1) He is married; (2) he has four children; (3) he is thinking of filing a case against his wife. Any two will do. The book’s key calls him Henry Arinto Sebastian with four children, but the posts are signed Samuel Gonzales and say three children (tatlong anak)."), ("3. The six questions he asked", "(1) Whether he could file a case against his wife who is having an affair; (2) whether he can use his wife’s website account as evidence; (3) how he could prove to the court the many instances he saw his wife sharing sweet moments with her lover; (4) what is the best thing to do; (5) whether his wife will lose custody of their children; (6) what is the appropriate case to be filed against his wife.")]
_S9 = [("Magpaumanhin kayo at magpatawaran kung may hinanakit sa isa’t isa.", "Say sorry and forgive each other if you have resentment towards each other."), ("Pinatawad kayo ng Panginoon kaya’t magpatawad din kayo.", "The Lord has forgiven you, hence you should also forgive."), ("At higit sa lahat, mag-ibigan kayo pagkat ito ang buklod ng ganap na pagkakaisa.", "And above all, love one another, because this is the bond of perfect unity.")]
L7 = lesson(
    "C24 L3 · FLO practice: court savings, a barangay blog, a saying on the wall",
    "Mga numero ng Katarungang Pambarangay · Barangay Onse Blog · Magpaumanhin at magpatawaran",
    requires=[],
    cards=[
        card("Activity 7: numbers (the book’s script)", "Listen to the sentences and write the numbers in figures. In the book the numbers are given already; here the spoken text is in words, and the figures are in the table below. Source of statistics: Dennis Carcamo of Philstar, May 23, 2014, “Govt saved P3.1B in court litigation last year: DILG.” The book’s first sentence reads “3,107,678,000 bilyong piso” (billion pesos), a slip, since 3,107,678,000 is itself about 3.1 billion. The book’s “63,651ng” and “11,597ng” are 63,651 na and 11,597 na kaso.", examples=passage(_A7)),
        card("Activity 7: the figures", "", tables=[table(["No.", "Figure"], _FIG, say=[])]),
        card("Activity 8: a netizen’s questions on a barangay blog", "Read the series of comments and questions of a netizen on a blog in answer to the announcement posted by a local barangay, then answer the questions. The book’s “3 anak” is written in words. The poster is Samuel Gonzales in the text.", examples=dlg(_B8)),
        card("Activity 8: the book’s key", "", tables=[table(["Question", "Answer"], [list(r) for r in _K8], say=[])]),
        card("Activity 9: a saying posted on the wall of a Barangay Justice System office", "Read the saying (the picture is naturally blurry; students decipher it). Source: gov.ph. The quotation marks are dropped in the spoken text. a) Rewrite the saying; b) give the English translation of the first two sentences.", examples=passage(_S9)),
        card("Activity 9: the book’s English key for the first two sentences", "1) Say sorry and forgive each other if you have resentment towards each other. 2) The Lord has forgiven you hence, you should also forgive."),
    ],
    exercises=uniq(
        tr_q(_A7) + rev_q(_A7) + tr_q(P(_B8)) + rev_q(P(_B8)) + tr_q(_S9) + rev_q(_S9)
        + [M("How many cases were settled outside court?", "three hundred twenty-seven thousand one hundred twenty-four", ["thirty-two thousand", "two hundred fifty-one thousand", "sixty-three thousand"], "327,124."), M("How many cases were solved through conciliation?", "two hundred fifty-one thousand eight hundred ninety-four", ["sixty-three thousand", "eleven thousand", "three hundred twenty-seven thousand"], "251,894."), M("How many cases were solved through mediation?", "sixty-three thousand six hundred fifty-one", ["eleven thousand", "two hundred fifty-one thousand", "three hundred thousand"], "63,651."), M("How many cases were solved through judgment?", "eleven thousand five hundred ninety-seven", ["sixty-three thousand", "three thousand", "two hundred thousand"], "11,597."), M("About how much did the courts save?", "three billion pesos", ["three million pesos", "thirty million pesos", "three hundred pesos"], "3.1 billion."), M("What is the announcement of the Barangay Onse Blog?", "ask questions about the Barangay Justice System before going to court", ["buy tickets", "join a sale", "pay taxes"], "tanong."), M("What is the poster’s first question?", "can he file a case against his wife who has another relationship", ["can he sell his house", "can he move abroad", "can he change his name"], "kasuhan ang asawa."), M("What is his only evidence?", "his wife’s fb account", ["a video", "a letter", "a witness"], "fb account."), M("What does he worry about regarding the children?", "whether his wife can lose rights over them", ["their schooling", "their food", "their health"], "karapatan sa mga anak."), M("What does the saying ask you to do if you have resentment?", "say sorry and forgive each other", ["file a case", "move away", "keep silent"], "magpaumanhin at magpatawaran."), M("Why should you forgive, per the saying?", "the Lord has forgiven you", ["it is the law", "it saves money", "it is easy"], "pinatawad kayo ng Panginoon."), M("What is the bond of perfect unity, per the saying?", "love", ["money", "law", "power"], "mag-ibigan.")]
        + [F("Nakatipid ang hukuman dahil sa Katarungang ___. (Pambarangay)", "Pambarangay", ["Pambansa", "Panlalawigan"], "Pambarangay."), F("Wala akong maipakitang ___ sa kort. (evidence)", "ebidensiya", ["bagyo", "regalo"], "ebidensiya."), F("Magpaumanhin kayo at ___ kung may hinanakit. (forgive each other)", "magpatawaran", ["magsuntukan", "magsigawan"], "magpatawaran."), F("Mag-ibigan kayo pagkat ito ang ___ ng pagkakaisa. (bond)", "buklod", ["batas", "kaso"], "buklod.")]
    ),
)

# ------------------------------------------------------------------ 8 listening 10-11
_N10 = [("Iginiit naman ng kampo ng pinaslang na Pilipinang transgender na si Jennifer Laude na hindi ito makikipag-areglo sa akusadong si US Marine LCPL Joseph Scott Pemberton. Giit ni Suarez, walang dahilan upang makipag-ayos sila kay Pemberton at ilalaban nila ang kaso hanggang sa huli.", "The camp of the slain Filipina transgender Jennifer Laude insisted that it will not settle with the accused, US Marine LCPL Joseph Scott Pemberton. Suarez insisted that there is no reason for them to make peace with Pemberton and that they will fight the case to the end."), ("Dalawang miyembro ng kidnap for ransom group ang patay matapos makipagbarilan kahapon sa mga awtoridad sa lungsod ng Davao. Ang kabuuang ulat mula kay Angel Dellera ng PTV Davao.", "Two members of a kidnap for ransom group were killed after a shootout yesterday with the authorities in Davao City. The full report from Angel Dellera of PTV Davao."), ("Handa umano ang nagtatagong founding Chairman ng MNLF o Moro National Liberation Front, Nur Misuari na makipagkita at makipagsundo sa Moro Islamic Liberation Front o MILF Chairman Al Hajji Murad.", "The hiding founding Chairman of the MNLF, the Moro National Liberation Front, Nur Misuari, is reportedly ready to meet and reach an agreement with Moro Islamic Liberation Front or MILF Chairman Al Hajji Murad."), ("Matapos pangunahan ang necrological service para sa tinaguriang Fallen Forty-Four, nakipagpulong si Pangulong Aquino sa mga pamilya ng mga nasawing bayaning pulis.", "After leading the necrological service for the so-called Fallen 44, President Aquino met with the families of the slain police heroes."), ("At sa Kabikulan naman po, Department of Agriculture at lalawigan ng Camarines Sur ay magtutulungan para sa pagpapaunlad ng pagsasaka.", "And in the Bicol region, the Department of Agriculture and the province of Camarines Sur will help each other for the development of farming."), ("Balita sa labas ng bansa, bukas ang North Korea na makipag-usap sa Amerika para mapawi ang tensiyon sa Korean Peninsula. Ayon sa Korean Central News Agency, nais ng Hilagang Korea na maki-isa sa seryosong diskusyon kabilang na ang layunin ng Amerika na tanggalin ang nuclear weapons.", "News from abroad, North Korea is open to talking with America to ease the tension on the Korean Peninsula. According to the Korean Central News Agency, North Korea wants to take part in a serious discussion including America’s aim to remove nuclear weapons.")]
_T10 = [["1", "(hindi) makikipag-areglo; (walang dahilan upang) makipag-ayos", "The aggrieved family of a Filipino transgender, Jennifer Laude, killed by US Marine LCPL Joseph Scott Pemberton finds no reason to enter into a settlement with him.", "conflict"], ["2", "makipagbarilan", "Two members of a kidnap for ransom group were killed after engaging in a shoot-out with authorities in Davao City yesterday.", "conflict"], ["3", "makipagkita; makipagsundo", "The MNLF Chairman Nur Misuari, who is in hiding, is reportedly ready to meet and forge an agreement with the MILF Chairman Al Hajj Murad.", "resolution"], ["4", "nakipagpulong", "President Aquino met with the families of slain soldiers after leading the necrological service of the Fallen 44.", "neither"], ["5", "magtutulungan", "In the Bicol region, the Department of Agriculture joined hands with the province of Camarines Sur to help improve farming.", "neither"], ["6", "makipag-usap; maki-isa", "North Korea is open to negotiate with the US to ease the tension in the Korean Peninsula. According to the Korean Central News Agency, North Korea hopes to cooperate in a serious discussion including the US objective of eradicating nuclear weapons.", "resolution"]]
_D11A = [("Tita Lydia", "Hello, Julia. Narinig kong magsasampa ka ng kaso laban kay Lita. Alam mo pumunta ka na lang sa Katarungang Pambarangay. Mas mabilis at hindi magastos.", "Hello, Julia. I heard you are going to file a case against Lita. You know, just go to the Katarungang Pambarangay. It is faster and not costly."), ("Julia", "Salamat, Tita Lydia. ’Yan din ang sabi ni Nanay para maayos agad.", "Thank you, Tita Lydia. That is also what Mother said so that it can be settled right away."), ("Tita Lydia", "Tama yun. Sakit pa kasi ng ulo kapag nagdemandahan kayo. Masalimuot ang proseso. Taon ang hihintayin mo at kailangan mong makakuha ng ebidensiya. Alam mo mahal ang abogado ngayon.", "That is right. It is a headache when you sue each other. The process is complicated. You will wait years and you need to get evidence. You know lawyers are expensive now.")]
_D11B = [("Julia", "Nakipagpulong nga ako sa barangay kanina. Gusto ko na ring kasing makipag-areglo kay Lita. Iniisip ko lang po paano kung ayaw makipag-ayos si Lita?", "I did meet with the barangay earlier. I also want to settle with Lita. I am just thinking, what if Lita does not want to make peace?"), ("Tita Lydia", "Ano bang sabi ni Kapitan?", "What did the Kapitan say?"), ("Julia", "Sabi naman ni Kapitan, kung hindi kami magkakasundo sa loob ng labinlimang araw, magkikita kami ulit para pumili raw ng tatlong tao mula sa Lupong Tagapamayapa na magiging kasapi ng Pangkat ng Tagapagkasundo.", "The Kapitan said, if we do not agree within fifteen days, we will meet again to choose three people from the Lupong Tagapamayapa who will be members of the Pangkat ng Tagapagkasundo."), ("Tita Lydia", "E, OK ba sayo yon?", "Is that okay with you?"), ("Julia", "OK lang. Mga kagalang-galang naman yung mga kasapi ng Lupon kaya OK lang sa akin kahit sino sa kanila.", "It is okay. The members of the Lupon are honorable, so it is okay with me whoever of them it is.")]
_K11 = [("Segment A, 1. Main idea", "The conflict between Rosa and Manang Lita. (The script names Julia and Lita.)"), ("Segment A, 2. Advice given", "She said to seek the help of the Barangay Justice System (BJS). The BJS is faster and inexpensive. Hiring a lawyer is expensive. And the court procedure is tedious and complicated. It takes years before the case is resolved and you need to gather evidence."), ("Segment A, 3. The advice of Julia’s mom", "She said the same thing as Aunt Lydia. She told Julia to seek the help of the BJS to settle the problem immediately."), ("Segment B, 4. What Julia did earlier", "She had a meeting with the barangay captain."), ("Segment B, 5. If the conflict is not resolved within fifteen days", "The Barangay Chair said, if an agreement is not reached within fifteen days, Julia and Lita will have to meet again. They will choose three people to become members of the Conciliatory Committee who will serve as mediators."), ("Segment B, 6. What Rosa thinks about the members of the Peace Team", "She thinks they are all honorable so she does not have any problem with any of them becoming part of the three-member panel in the Conciliatory Committee. (The script has Julia saying this.)")]
L8 = lesson(
    "C24 L3 · Listening: reciprocal verbs in the news; advice about a case",
    "Makipag-areglo, makipagbarilan, makipagpulong · Katarungang Pambarangay: mas mabilis at hindi magastos",
    requires=[],
    cards=[
        card("Activity 10: six news items (the book’s scripts)", "a. Listen to the passages and write the simple or reciprocal social verbs mentioned (maki-, mag-an, makipag-, makipag-an); in some numbers there is more than one. b. Check what each passage is about, conflict, resolution or neither, and compare with a partner. c. Be ready to conjugate the verbs. The book’s sources are PTV news clips on YouTube. “Fallen 44” is written Fallen Forty-Four in the spoken text. The English glosses in the next card are the book’s (lightly corrected), and the conflict, resolution or neither column is my reading since the book’s key leaves it blank.", examples=passage(_N10)),
        card("Activity 10: the book’s key", "The book’s “agrieved”, “Jenneifer”, “Presaident” and “negotiaate” are corrected.", tables=[table(["No.", "Social verb", "What the news is about", "My reading"], _T10, say=[])]),
        card("Activity 11, Segment A: advice about a case (the book’s script)", "Listen to the exchanges between friends, then answer the questions. The book’s key calls the speakers Rosa, Manang Lita and Aunt Lydia, but the script has Julia, Lita and Tita Lydia; I follow the script.", examples=dlg(_D11A)),
        card("Activity 11, Segment B (the book’s script)", "", examples=dlg(_D11B)),
        card("Activity 11: the book’s key", "", tables=[table(["Question", "Answer"], [list(r) for r in _K11], say=[])]),
    ],
    exercises=uniq(
        tr_q(_N10) + rev_q(_N10) + tr_q(P(_D11A)) + rev_q(P(_D11A)) + tr_q(P(_D11B)) + rev_q(P(_D11B))
        + [M("Which verb is used for Jennifer Laude’s family refusing to settle?", "makipag-areglo", ["makipagbarilan", "makipagkita", "makipag-usap"], "hindi makikipag-areglo."), M("Which verb is used for the shoot-out in Davao?", "makipagbarilan", ["makipagkita", "makipagpulong", "magtutulungan"], "makipagbarilan."), M("Which verbs are used for Nur Misuari being ready to meet and make an agreement?", "makipagkita and makipagsundo", ["makipagbarilan and makipag-usap", "magtutulungan and makiisa", "makipag-ayos and makipagpulong"], "makipagkita at makipagsundo."), M("Which verb is used for President Aquino meeting with the families?", "nakipagpulong", ["makipagkita", "magtutulungan", "makipag-usap"], "nakipagpulong."), M("Which verb is used for the Department of Agriculture and Camarines Sur?", "magtutulungan", ["makipagbarilan", "nakipagpulong", "makiisa"], "magtutulungan."), M("Which verbs are used for North Korea?", "makipag-usap and maki-isa", ["makipagkita and makipagsundo", "makipagbarilan and makipagpulong", "magtutulungan and makipag-ayos"], "makipag-usap, maki-isa."), M("Where did the kidnap for ransom group members die?", "Davao City", ["Manila", "Cebu", "Cotabato"], "lungsod ng Davao."), M("What advice does Tita Lydia give Julia?", "go to the Katarungang Pambarangay", ["hire a lawyer", "ignore Lita", "move away"], "pumunta ka na lang."), M("Why is the barangay better than court, per Tita Lydia?", "it is faster and not costly", ["it is far", "it is secret", "it is for the rich"], "mas mabilis at hindi magastos."), M("What does a case in court require, per Tita Lydia?", "years of waiting and evidence", ["a few days", "a small fee", "no effort"], "taon ang hihintayin."), M("Within how many days must they agree, per the Kapitan?", "fifteen days", ["five days", "thirty days", "one day"], "labinlimang araw."), M("How many people will be chosen from the Lupon for the Pangkat?", "three", ["one", "five", "ten"], "tatlong tao.")]
        + [F("Hindi ito makikipag-___ sa akusado. (settle)", "areglo", ["pulong", "kita"], "makipag-areglo."), F("Dalawang miyembro ang patay matapos ___. (shoot it out)", "makipagbarilan", ["makipagkita", "makipagpulong"], "makipagbarilan."), F("Kung hindi kami magkasundo sa loob ng ___ araw. (fifteen)", "labinlimang", ["limang", "tatlong"], "labinlimang."), F("Mas mabilis at hindi ___ ang Katarungang Pambarangay. (costly)", "magastos", ["masalimuot", "mahirap"], "magastos.")]
    ),
)

# ------------------------------------------------------------------ 9 listening 12 + speaking + glossary
_D12 = [("Segment A", "Unang Tagapagsalita", "Ano’ng nangyari sayo? May problema ka na naman?", "What happened to you? Do you have a problem again?"), ("Segment A", "Ikalawang Tagapagsalita", "Si Val kasi e. Sulsulan ba naman si Niko. Nagkasuntukan tuloy kami. Alam mo kung may kapangyarihan lang talaga ako, yari sa akin ’yun. Lilipad ako, pupuntahan ko ang bahay nun at papaulanan ko ng bato. Ewan ko kung ’di magkabukol ’yun. Teka, teka, sa’n ba tayo pupunta?", "It is Val, you see. He had to egg on Niko. So we ended up punching each other. You know, if I only had power, he would be in trouble. I would fly, go to his house and rain rocks on it. I do not know if he would not get a bump. Wait, wait, where are we going?"), ("Segment A", "Unang Tagapagsalita", "Pupunta tayo sa barangay. Ayusin natin ’yung problema n’yo ni Val. ’Wag nating gagantihan si Val, ha? Dun tayo pupunta, masama ’yun e.", "We are going to the barangay. Let us fix your problem with Val. Let us not retaliate against Val, okay? That is where we are going, that is bad."), ("Segment A", "Ikalawang Tagapagsalita", "Teka, teka, sa’n ba kasi tayo pupunta?", "Wait, wait, where are we really going?"), ("Segment A", "Unang Tagapagsalita", "Basta, pupunta tayo sa barangay. Ayusin natin ’yung problema n’yo ni Val. May katarungang pambarangay tayong tinatawag.", "Anyway, we are going to the barangay. Let us fix your problem with Val. We have what is called the katarungang pambarangay."), ("Segment B", "Ikalawang Tagapagsalita", "Ano ba kasi ’yang katarungang pambarangay na ’yan?", "What is that katarungang pambarangay anyway?"), ("Segment B", "Unang Tagapagsalita", "Basta, ’to ’yung pagkakasunduin kayo ni Val nito. Tutal, pareho naman kayong taga-dito sa Barangay Silahis, e. Dito n’yo na susulusyunan ang problema ninyo. ’Wag na ninyong dalhin pa sa korte ’yan. Bukod sa matagal pa ang proseso, gagastusan pa nang malaki.", "This is what will make you and Val agree. After all, you are both from here in Barangay Silahis. Here you will solve your problem. Do not bring that to court anymore. Besides the process being long, it will cost a lot."), ("Segment B", "Ikalawang Tagapagsalita", "Ibig mong sabihin sa barangay puwede nang makamit ang hustisya?", "You mean justice can already be achieved at the barangay?"), ("Segment B", "Unang Tagapagsalita", "Mabilis ang hustisya d’yan.", "Justice is fast there."), ("Segment B", "Ikalawang Tagapagsalita", "Teka, teka. Ano ba ’yung sinabi mo kanina?", "Wait, wait. What was it that you said earlier?"), ("Segment B", "Unang Tagapagsalita", "Sabi ko, mas mabilis ang hustisya sa Katarungang Pambarangay. Hindi mo na kailangang daanin sa masalimuot na pagsasampa ng kaso sa korte.", "I said, justice is faster at the Katarungang Pambarangay. You no longer need to go through the complicated filing of a case in court."), ("Segment B", "Ikalawang Tagapagsalita", "Oo nga naman, kasi kung hindi na natin dadalhin sa korte ang problema at sosolusyunan na. Dito pa lang sa barangay, e, hindi na madadagdagan ’yung napakaraming kaso na nakabinbin sa korte.", "That is true, because if we will no longer bring the problem to court and will solve it already. Right here at the barangay, the very many pending cases in court will not increase."), ("Segment C", "Unang Tagapagsalita", "’Yun ’di ba? So, tara na. Pasok na tayo sa loob.", "Right? So, let us go. Let us go inside."), ("Segment C", "Ikalawang Tagapagsalita", "Teka, teka, papasok na tayo kaagad. Wala nga akong ebidensiya, e. Baka hindi nila ako paniwalaan diyan.", "Wait, wait, we are going in right away. I do not have evidence, you see. They might not believe me there."), ("Segment C", "Unang Tagapagsalita", "Sshh. ’Sus ko! Ano ka ba? Sa Katarungang Pambarangay, hindi mo na kailangang magprisinta ng sangkaterbang ebidensiya gaya ng ginagawa sa korte. Dito, paghaharapin na lang kayo ni Val ng Kapitan at ilang usapan lang, ayos na ang problema. Hindi tulad yung sa korte aabutan ng ilang taon bago matuldukan ’yang usapan na ’yan.", "Shh. Goodness! What is wrong with you? At the Katarungang Pambarangay, you no longer need to present a heap of evidence as is done in court. Here, the Kapitan will just make you and Val face each other and after a few talks, the problem is fixed. Unlike in court, it will take several years before that matter is ended."), ("Segment C", "Ikalawang Tagapagsalita", "E, paano kung hindi kami magkasundo sa harap ng Kapitan? Halimbawa, ayaw makinig nung Val na ’yun sa rekomendasyon nung Kapitan.", "And what if we do not agree in front of the Kapitan? For example, that Val does not want to listen to the Kapitan’s recommendation."), ("Segment C", "Unang Tagapagsalita", "Kung hindi, e, bubuo ng pangkat ng lupon ’yung Kapitan.", "If not, the Kapitan will form a team of the lupon."), ("Segment D", "Ikalawang Tagapagsalita", "E, ilan naman ang bumubuo sa tinatawag mong lupon na ’yan?", "And how many make up what you call that lupon?"), ("Segment D", "Unang Tagapagsalita", "Tatlo. Tatlo sila. Dapat hindi bias at hindi kamag-anak ang pangkat ng lupon na ’yan. Anuman ang mapagdesisyunan o mapagbotohan ng lupon ay final na. Hindi na puwedeng mabawi.", "Three. There are three of them. The team of that lupon must not be biased and must not be relatives. Whatever the lupon decides or votes on is final. It can no longer be taken back."), ("Segment D", "Ikalawang Tagapagsalita", "E, paano nga kung hindi pa rin kami magkasundo kahit nandiyan na ’yung lupon?", "And what if we still do not agree even when the lupon is there?"), ("Segment D", "Unang Tagapagsalita", "E, kung hindi n’yo tatanggapin ni Val ’yung napagkasunduan ninyo ng pangkat na ’yan, dadalhin na ’yan sa korte. E, goodluck na lang. Ang proseso ang tagal-tagal nun, masalimuot.", "Well, if you and Val will not accept what you agreed on with that team, it will be brought to court. Well, good luck then. The process takes so long, it is complicated."), ("Segment D", "Ikalawang Tagapagsalita", "Pero alam mo, sa tingin ko, magkakasundo naman kami ni Val niyan. May pinagsamahan naman kasi kami nun e.", "But you know, I think Val and I will agree about that. We do have a shared history, you see.")]
